from pathlib import Path
import re,json,html
root=Path('.')
original=Path('backup/TITAN.original.md').read_text(encoding='utf-8')
parts=re.split(r'\n---\n(?:layout: default\nclass: titan\n---\n)?',original)
# Capture the original scientific detail as notes, one source topic per entry.
chunks=re.split(r'\n---\nlayout: default\nclass: titan\n---\n',original)
notes=[]
for c in chunks:
 c=re.sub(r'(?s)<style>.*?</style>','',c)
 c=re.sub(r'<img[^>]+>','',c)
 c=re.sub(r'<[^>]+>','',c)
 c=re.sub(r'(?s)^---.*?---','',c)
 c=c.replace('[Verify in Paper]','[Source limitation: detail not established in supplied PDF; do not infer.]')
 notes.append(c.strip())
slides=[]
def add(title,body,src,topic=0,extra='',klass=''):
 slides.append(dict(title=title,body=body,src=src,topic=topic,extra=extra,klass=klass))
def reveal(body,n=1):return f'<div v-click="{n}">{body}</div>'
def fig(name,cap,n=1,cls=''):
 return f'<figure v-click="{n}" class="{cls}"><img src="/figures/{name}.png" alt="{html.escape(cap)}"><figcaption>{cap}</figcaption></figure>'
def point(head,body='',n=None):
 a=f'<div class="point"><h2>{head}</h2><p>{body}</p></div>'
 return reveal(a,n) if n is not None else a
def columns(a,b):return f'<div class="columns"><div>{a}</div><div>{b}</div></div>'
def flow(items):
 return '<div class="flow">'+''.join(f'<div class="node" '+(f'v-click="{n}"' if n else '')+f'><span class="step">{i+1:02}</span><h2>{h}</h2><p>{t}</p></div>' for i,(h,t,n) in enumerate(items))+'</div>'
def table(headers,rows):
 return '<table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def chart(title,values,metric,n=1):
 colors=['#a32638','#dc8f86','#9c73a8','#328b91','#d5b64b','#5283bb']
 names=['TITAN','TITANᵥ','Mean','PRISM','GigaPath','CHIEF']
 b=''.join(f'<div class="bar-row"><span>{name}</span><div class="track"><div style="width:{v*100}%;background:{color}"></div></div><b>{v:.3f}</b></div>' for name,v,color in zip(names,values,colors))
 return f'<div v-click="{n}" class="chart"><h2>{title}</h2><p class="metric">{metric} · scale 0–1</p>{b}</div>'
