head="""---
theme: default
title: 'TITAN: A multimodal whole-slide foundation model for pathology'
colorSchema: light
aspectRatio: 16/9
canvasWidth: 1280
transition: fade
mdc: false
fonts:
  sans: Arial
  provider: none
  local: Arial
  italic: false
drawings:
  enabled: false
  persist: false
download: false
exportFilename: TITAN-guided
export:
  withClicks: false
defaults:
  layout: default
  class: titan
---
"""
result=head
for i,s in enumerate(slides):
 if i:result+='\n---\nlayout: default\nclass: titan '+s['klass']+'\n---\n'
 result+='\n# '+s['title']+'\n\n'+s['body']+f'\n\n<div class="source">{s["src"]}</div><div class="page-number">{i+1:02}</div>\n\n'
 result+='<!--\n'+s['extra']+'\n\nSource detail retained from original topic (for presenter reference):\n'+notes[s['topic']]+'\n-->\n'
result=re.sub(r'\$\$(.*?)\$\$',lambda m: '<Formula tex="'+html.escape(m[1],quote=True)+'" />',result)
Path('TITAN.md').write_text(result,encoding='utf-8')
pkg=json.loads(Path('package.json').read_text());pkg['scripts']={'dev':'slidev TITAN.md','build':'slidev build TITAN.md','export':'slidev export TITAN.md --output output/TITAN-guided.pdf','export:steps':'slidev export TITAN.md --with-clicks --output output/TITAN-reveal-states.pdf','check':'node scripts/check-deck.cjs'};Path('package.json').write_text(json.dumps(pkg,indent=2)+'\n')
print('Wrote',len(slides),'slides;',23,'main +',len(slides)-23,'backup')
